create table network4 as select distinct a.*, b.indexcat as dow
from network3 as a left join index.dow_nasdaq as b
on b.from<=a.datadate and (a.datadate<=b.thru or b.thru=.) and a.gvkey=b.gvkey and b.conm="Dow Jones Industrials-30 Stk";
quit;

* segments;
proc sql;
create table segment as select distinct gvkey, datadate, sum(case when STYPE="BUSSEG" then 1 else 0 end) as bus_seg, sum(case when STYPE="GEOSEG" then 1 else 0 end) as geo_seg
from fund.segment
group by gvkey, datadate;
quit;

