create table hopping19 as select distinct a.*, b.tdc1 as tdc1_new
from hopping18 as a left join comp as b
on a.gvkey_new=b.gvkey and a.year=b.year;
quit;

create table paypeer1 as select distinct a.*, b.sic, b.sale, c.sic as sic_peer, c.sale as sale_peer
from paypeer as a left join comp.funda as b
on a.gvkey=b.gvkey and a.fyear=b.fyear+1
left join comp.funda as c
on a.fyear=c.fyear+1 and a.gvkey_peer=c.gvkey;
quit;

data funda;
set comp.ccmfunda_0428;
sic2=floor(sic/100);
if mkvalt=. then mkvalt=prcc_f*csho;
roa=ib/at;
keep gvkey lpermno datadate fyear fyrc sic2 naics sale mkvalt roa at;
run;

create table ret5 as select distinct a.permno, a.date, a.year, exp(sum(log(1+a.return)))-1 as ret, a.mkvalt
from ret4 as a
group by permno, date;

create table ret22 as select distinct a.*, b.ret_ind_ew
from ret21 as a, ret_ind as b
where a.bdate=b.date and a.sic2=b.sic2 and a.rank=b.rank;
quit;

