proc sql;
create table peer11 as select distinct a.fyear, a.cik_own, a.gvkey_own, a.tdc_own, a.cik_peer, a.gvkey_peer, a.tdc_peer
from peer2 as a, peer2 as b
where a.fyear=b.fyear and a.cik_peer=b.cik_own;

create table rpe3 as select distinct a.*, b.idio_var, b.corr
from rpe2 as a full join control as b
on a.gvkey=b.gvkey and a.fyear=b.fyear;
quit;

proc sort data=rpe3 nodupkey;

create table analyst as select distinct a.*, b.gvkey
from ibes.analyst_detail as a, ibes.cibeslnk as b
where a.ticker=b.ticker and b.fdate<=a.anndats<=b.ldate;
